{
  "title": "Detect Kerberoasting with RC4 Downgrade",
  "id": "a1b2c3d4-kerberoast-rc4",
  "description": "Detects Kerberos TGS requests for service accounts using RC4 encryption, indicative of Kerberoasting attempts.",
  "status": "test",
  "author": "SOC",
  "date": "2026-09-30",
  "logsource": {
    "product": "windows",
    "service": "security"
  },
  "detection": {
    "selection": {
      "EventID": 4769,
      "TicketEncryptionType": "RC4"
    },
    "filter_service_accounts": {
      "ServiceName": ["svc_sql_prod", "svc_exchange_admin", "svc_sccm"]
    },
    "condition": "selection and filter_service_accounts"
  },
  "fields": ["SubjectUserName", "ServiceName", "TicketEncryptionType", "SourceIP"],
  "level": "high"
}

{
  "title": "Pass-the-Hash SMB Auth with Domain Admin Account",
  "id": "c3b9f6e2-xxxx-xxxx-xxxx-xxxxxxxxxxxx",
  "status": "experimental",
  "description": "Detect SMB authentication using NTLM hash of a domain admin account, indicating possible pass-the-hash.",
  "author": "SOC Team",
  "logsource": {
    "product": "windows",
    "service": "security"
  },
  "detection": {
    "selection": {
      "EventID": 4624,
      "AuthenticationPackageName": "NTLM",
      "LogonType": 3,
      "TargetUserName|contains": "admin"
    },
    "condition": "selection"
  },
  "falsepositives": ["Legitimate use of admin accounts for remote management"],
  "level": "high"
}
